/* ===== BUSINESS PROFILE ===== */
const DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const hoursTable=h=>`<div class="table-w"><table class="tbl"><tbody>${[1,2,3,4,5,6,0].map(d=>`<tr class="${new Date().getDay()===d?'hl':''}"><th scope="row" style="background:none">${t(DAYS[d])}</th><td>${h[d]?f12(h[d][0])+' – '+f12(h[d][1]):'<span class="badge bad">'+t('Closed')+'</span>'}</td></tr>`).join('')}</tbody></table></div>`;
function profileHead(x,isS){const o=openState(x),d=dist(x),rv=D().reviews.filter(r=>r.tid===x.id&&r.status==='published');
 return `<div class="card" style="overflow:visible"><div class="art w" style="--h:${x.hue};border-radius:var(--r-lg) var(--r-lg) 0 0">${'<span>'+x.emoji+'</span>'}</div><div class="pad" style="padding:0 16px 16px"><div class="row" style="align-items:flex-end;margin-top:-34px"><div class="art mini" style="--h:${x.hue};width:72px;height:72px;font-size:2.2rem;border:4px solid var(--surface);border-radius:20px">${x.emoji}</div></div><div class="stack" style="gap:6px;margin-top:8px"><div class="row wrap-r" style="gap:8px"><h1 style="font-size:1.4rem">${esc(nm(x.name))}</h1>${x.verified?vBadge():''}</div><div class="t2">${esc(catName(x.cat))} · ${esc(areaName(x.area))}</div><div class="row wrap-r" style="gap:8px">${stars(x.rating,16)}<b>${x.rating.toFixed(1)}</b><span class="muted">(${rv.length>=1?x.rc:x.rc} ${t('reviews')})</span><span>·</span><span>${ic('pin',14)} ${d.toFixed(1)} km</span></div><div class="row wrap-r" style="gap:8px">${openBadge(x)}${o.sub?`<span class="small muted">${esc(o.sub)}</span>`:''}${!isS?delivBadge(x):''}</div></div></div></div>`}
function actionBar(x,isS){return `<div class="actionbar noprint" role="toolbar" aria-label="${t('Quick actions')}"><a class="btn p" href="${telH(x.phone)}">${ic('phone',20)}${t('Call')}</a><a class="btn s" target="_blank" rel="noopener" href="${waH(x.wa,'Hi, I found you on ApnaTown.')}">${ic('chat',20)}WhatsApp</a><a class="btn g" target="_blank" rel="noopener" href="${mapsDir(x)}">${ic('nav',20)}${t('Directions')}</a><button class="btn g" data-act="share" data-id="${x.id}">${ic('share',20)}${t('Share')}</button><button class="btn g" data-act="bm" data-id="${x.id}" aria-pressed="${isBm(x.id)}">${ic('bookmark',20)}${isBm(x.id)?t('Saved'):t('Save')}</button></div>`}
const unavailable=x=>`<div class="stack">${alertBox('warn',`<b>${t('This listing is not live')}</b> (${t(AP[x.status]?AP[x.status][0]:x.status)}). ${t('Customers can’t see it yet.')}`)}</div>`;
V.biz=id=>{const b=biz(id);if(!b)return V.nf();rec(id);const tabs=[['about','About'],['products','Products'],['offers','Offers'],['gallery','Gallery & Videos'],['reviews','Reviews'],['contact','Contact & Location']];const tab=UI.btab;
 const prods=D().products.filter(p=>p.bid===id&&p.status==='active'),subs=[...new Set(prods.map(p=>p.sub))],ofs=D().offers.filter(o=>o.bid===id&&o.status==='active'),rv=D().reviews.filter(r=>r.tid===id&&r.status==='published');
 const di=delivInfo(b);let body='';
 if(tab==='about')body=`<div class="stack"><div class="card pad stack"><h3>${t('About')}</h3><p>${esc(b.desc)}</p><dl class="kv"><dt>${t('Since')}</dt><dd>${b.since}</dd><dt>${t('Address')}</dt><dd>${esc(b.addr)}</dd></dl></div>
  <div class="card pad stack"><h3>${t('Delivery & pickup')}</h3>${di.ok?alertBox('ok',`<b>${t('Delivers to your address')}</b> · ${di.d.toFixed(1)} km · ${t('Delivery')} ${di.fee?inr(di.fee):t('Free')}`,'truck'):alertBox('warn',`<b>${t('Outside delivery range')}</b> · ${di.d.toFixed(1)} km ${t('away; delivery radius')} ${b.del.radius} km. ${b.del.pickup?t('You can still choose self-pickup.'):''}`,'pin')}
  <dl class="kv"><dt>${t('Delivered by')}</dt><dd>${b.del.mode==='self'?t('Shop’s own delivery'):t('ApnaTown rider')}</dd><dt>${t('Delivery radius')}</dt><dd>${b.del.radius} km</dd><dt>${t('Delivery charge')}</dt><dd>${b.del.mode==='self'?inr(b.del.fee):t('By distance')+' ('+inr(D().cfg.slabs[0].fee)+'+)'}</dd><dt>${t('Minimum order')}</dt><dd>${inr(b.del.min)}</dd><dt>${t('Self-pickup')}</dt><dd>${b.del.pickup?t('Available'):t('Not available')}</dd></dl>${b.del.pickup?`<div class="small t2">${ic('info',14)} ${esc(b.del.note)}</div>`:''}</div>
  <div class="card pad stack"><h3>${t('Opening hours')}</h3>${hoursTable(b.hours)}</div><button class="btn t sm" data-act="reportBiz" data-id="${id}" style="justify-self:start">${ic('flag',16)} ${t('Report this business')}</button></div>`;
 if(tab==='products')body=prods.length?`<div class="stack-lg">${subs.map(s=>`<section><h3 style="margin-bottom:8px">${esc(s)}</h3><div class="grid auto-s">${prods.filter(p=>p.sub===s).map(prodCard).join('')}</div></section>`).join('')}</div>`:empty('📦','No products yet','This shop hasn’t added products.');
 if(tab==='offers')body=`<div class="stack">${ofs.length?ofs.map(o=>`<div class="card pad stack" style="background:linear-gradient(135deg,var(--offer-soft),var(--surface))"><span class="badge offer" style="justify-self:start">${o.type==='percent'?o.value+'% '+t('OFF'):o.type==='flat'?'₹'+o.value+' '+t('OFF'):t('Free delivery')}</span><h3>${esc(o.title)}</h3><div class="small t2">${t('Valid till')} ${fdate(o.to)}</div>${o.pids.length?`<div class="grid auto-s">${o.pids.map(pid=>prod(pid)).filter(Boolean).map(prodCard).join('')}</div>`:''}</div>`).join(''):empty('🏷️','No offers right now','Check back soon.')}</div>`;
 if(tab==='gallery')body=`<div class="stack"><div class="grid g3">${b.gallery.map((g,i)=>`<button class="card" style="padding:0;border:1px solid var(--border)" data-act="lightbox" data-id="${id}" data-i="${i}" aria-label="${t('Open photo')} ${i+1}">${art(g,b.hue+i*20,'f')}</button>`).join('')}</div>${b.social.yt||true?`<div class="card pad row"><div class="mini art" style="--h:0">▶️</div><div class="grow"><b>${t('Shop video tour')}</b><div class="small t2">${t('Videos play on YouTube. If your connection is slow, tap to open.')}</div></div><a class="btn g sm" target="_blank" rel="noopener" href="https://www.youtube.com/results?search_query=${encodeURIComponent(b.name.en)}">${t('Watch')}</a></div>`:''}<div class="card pad row"><div class="mini art" style="--h:330">📷</div><div class="grow"><b>Instagram</b><div class="small t2">${b.social.ig?'@'+esc(b.social.ig):t('Latest posts and reels')}</div></div><a class="btn g sm" target="_blank" rel="noopener" href="https://www.instagram.com/${encodeURIComponent(b.social.ig||'')}">${t('Open')}</a></div></div>`;
 if(tab==='reviews')body=`<div class="stack"><div class="card pad">${ratingBreak(rv)}</div><a class="btn p" href="#rev-${id}">${ic('star',18)} ${t('Write a review')}</a>${rv.length?rv.map(r=>revCard(r,S.user&&r.uid==='u1')).join(''):empty('⭐','No reviews yet','Be the first to share your experience.')}</div>`;
 if(tab==='contact')body=`<div class="stack"><div class="card pad stack"><h3>${t('Contact')}</h3><dl class="kv"><dt>${t('Phone')}</dt><dd><a href="${telH(b.phone)}">+91 ${esc(b.phone)}</a></dd><dt>WhatsApp</dt><dd><a href="${waH(b.wa)}" target="_blank" rel="noopener">+91 ${esc(b.wa)}</a></dd><dt>Email</dt><dd>${esc(b.email)}</dd><dt>${t('Address')}</dt><dd>${esc(b.addr)}</dd></dl></div>${mapSvg('bmap',[b],{radius:0,sel:b.id})}<a class="btn p" target="_blank" rel="noopener" href="${mapsDir(b)}">${ic('nav',18)} ${t('Get directions')}</a>
  <div class="card qrbox"><h3>${t('Scan to open this shop')}</h3>${qrSvg(shareUrl('biz-'+id),b.emoji)}<div class="small muted">${esc(shareUrl('biz-'+id))}</div><div class="row"><button class="btn g sm" data-act="copy" data-v="${esc(shareUrl('biz-'+id))}">${ic('copy',16)} ${t('Copy link')}</button><button class="btn g sm" data-act="share" data-id="${id}">${ic('share',16)} ${t('Share')}</button></div></div></div>`;
 return `<div class="stack" style="margin-bottom:6px"><div class="crumb"><a href="#home">${t('Home')}</a> / <a href="#cat-${b.cat}">${esc(catName(b.cat))}</a> / <span>${esc(nm(b.name))}</span></div>${b.status!=='approved'?unavailable(b):''}${profileHead(b)}</div>${actionBar(b)}<div class="tabs" role="tablist" style="margin-top:12px">${tabs.map(([k,l])=>`<button role="tab" aria-selected="${tab===k}" class="${tab===k?'on':''}" data-act="btab" data-v="${k}">${t(l)}</button>`).join('')}</div>${body}`};
A.btab=el=>{UI.btab=el.dataset.v;render(true)};
A.lightbox=el=>{const b=ent(el.dataset.id),i=+el.dataset.i;sheet(`<div class="stack center">${art(b.gallery[i],b.hue+i*20,'w')}<div class="row between"><button class="btn g sm" data-act="lightbox" data-id="${b.id}" data-i="${(i+b.gallery.length-1)%b.gallery.length}">${ic('cl',16)}</button><span class="small muted">${i+1} / ${b.gallery.length}</span><button class="btn g sm" data-act="lightbox" data-id="${b.id}" data-i="${(i+1)%b.gallery.length}">${ic('cr',16)}</button></div></div>`,{label:'Photo'})};
A.reportBiz=el=>{sheet(`<h3>${t('Report this listing')}</h3><form data-form="report" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${el.dataset.id}">${field('Reason','reason','',{type:'select',opts:[['fake','Fake or misleading'],['wrong','Wrong details'],['abuse','Abusive content'],['closed','Shop is closed permanently']]})}${field('Details (optional)','d','',{type:'textarea'})}<button class="btn p">${t('Submit report')}</button></form>`)};
F.report=d=>{closeSheet();notify('admin','Listing reported',ent(d.id)?nm(ent(d.id).name)+' · '+d.reason:d.reason,'alistings','sys');save();toast(t('Thanks. Our team will review it.'),'flag')};
/* ===== PRODUCT ===== */
V.prod=id=>{const p=prod(id);if(!p)return V.nf();rec(id);const b=biz(p.bid),op=offerPrice(p),out=!p.avail||p.stock<=0;const v=UI.pvar[id]||p.variants[0]||'';const disc=p.mrp>op?Math.round((1-op/p.mrp)*100):0,di=delivInfo(b);const rv=D().reviews.filter(r=>r.tid===id&&r.status==='published'),rel=D().products.filter(x=>x.cat===p.cat&&x.id!==id&&x.avail).slice(0,6);
 const inCart=S.cart.find(c=>c.pid===id&&!c.saved);
 return `<div class="stack-lg"><div class="crumb"><a href="#home">${t('Home')}</a> / <a href="#cat-${p.cat}">${esc(catName(p.cat))}</a> / <span>${esc(nm(p.name))}</span></div>
 <div class="cols2 eq"><div><div class="hero" aria-label="${t('Product images')}">${[0,1,2].map(i=>`<div style="flex:0 0 100%;scroll-snap-align:start">${art(p.emoji,p.hue+i*25,'f')}</div>`).join('')}</div><div class="dots">${[0,1,2].map(i=>`<i class="${i?'':'on'}"></i>`).join('')}</div></div>
 <div class="stack"><h1>${esc(nm(p.name))}</h1><div class="row">${stars(b.rating)}<span class="small muted">${rv.length} ${t('reviews')}</span></div><div><span class="price" style="font-size:1.6rem">${inr(op)}</span>${p.mrp>op?`<span class="mrp">${inr(p.mrp)}</span><span class="off">${disc}% ${t('OFF')}</span>`:''}<div class="xs muted">${t('Inclusive of all taxes')} · ${esc(p.unit)}</div></div>
 ${p.variants.length?`<div><div class="lbl small">${t('Choose')}</div><div class="chips">${p.variants.map(x=>`<button class="chip ${x===v?'on':''}" data-act="pvar" data-id="${id}" data-v="${esc(x)}" aria-pressed="${x===v}">${esc(x)}</button>`).join('')}</div></div>`:''}
 ${out?alertBox('bad',`<b>${t('Out of stock')}</b>`)+`<button class="btn o" data-act="notifyMe" data-id="${id}">${ic('bell',18)} ${t('Notify me when available')}</button>`:p.stock<=p.low?alertBox('warn',`<b>${t('Only')} ${p.stock} ${t('left')}</b> ${t('Order soon.')}`):`<span class="badge ok">✓ ${t('In stock')}</span>`}
 ${out?'':`<div class="row"><div class="stepper" role="group" aria-label="${t('Quantity')}"><button data-act="pq" data-d="-1" aria-label="${t('Decrease')}">−</button><b>${UI.pqty}</b><button data-act="pq" data-d="1" aria-label="${t('Increase')}">+</button></div><span class="small muted">${t('Max')} ${Math.min(10,p.stock)}</span></div><div class="row"><button class="btn o grow" data-act="addCart" data-id="${id}">${ic('cart',18)} ${inCart?t('Add more'):t('Add to cart')}</button><button class="btn p grow" data-act="buyNow" data-id="${id}">${t('Buy now')}</button></div>`}
 <div class="row"><button class="btn t sm" data-act="share" data-id="${id}">${ic('share',16)} ${t('Share product')}</button></div></div></div>
 <div class="card pad stack"><h3>${t('Sold by')}</h3><a class="row" href="#biz-${b.id}">${art(b.emoji,b.hue,'mini')}<div class="grow"><b>${esc(nm(b.name))}</b><div class="small t2">${stars(b.rating)} ${b.rating.toFixed(1)} · ${dist(b).toFixed(1)} km · ${openState(b).label}</div></div>${ic('cr')}</a><div class="divider"></div>${di.ok?`<div class="small">${ic('truck',16)} <b>${t('Delivers to you')}</b> · ${di.fee?inr(di.fee):t('Free')} ${t('delivery')}</div>`:`<div class="small">${ic('pin',16)} ${t('Outside delivery range. Self-pickup available.')}</div>`}${b.del.pickup?`<div class="small">${ic('store',16)} ${t('Self-pickup available')}</div>`:''}</div>
 <div class="card pad stack"><h3>${t('Details')}</h3><p>${esc(p.desc)}</p><dl class="kv">${p.specs.map(s=>`<dt>${esc(s[0])}</dt><dd>${esc(s[1])}</dd>`).join('')}<dt>SKU</dt><dd>${esc(p.sku)}</dd></dl></div>
 <section><div class="sec" style="margin-top:0"><h2>${t('Ratings & reviews')}</h2><a class="btn o sm" href="#rev-${id}">${t('Write a review')}</a></div><div class="stack">${rv.length?`<div class="card pad">${ratingBreak(rv)}</div>`+rv.map(r=>revCard(r,S.user&&r.uid==='u1')).join(''):empty('⭐','No reviews yet','Be the first to review this product.')}</div></section>
 ${rel.length?sec('Related products')+`<div class="hscroll">${rel.map(prodCard).join('')}</div>`:''}</div>`};
A.pvar=el=>{UI.pvar[el.dataset.id]=el.dataset.v;render(true)};A.pq=el=>{UI.pqty=clamp(UI.pqty+ +el.dataset.d,1,10);render(true)};
A.notifyMe=el=>{if(needLogin('Log in and we’ll tell you when it is back.'))return;toast(t('We will notify you when it is back'),'bell')};
function addToCart(pid,qty,variant){const p=prod(pid);if(!p||!p.avail||p.stock<=0){toast(t('Out of stock'),'alert');return false}const v=variant??(UI.pvar[pid]||p.variants[0]||'');const c=S.cart.find(x=>x.pid===pid&&x.variant===v&&!x.saved);if(c)c.qty=Math.min(10,p.stock,c.qty+qty);else S.cart.push({pid,qty:Math.min(qty,p.stock),variant:v});save();return true}
A.addCart=el=>{if(addToCart(el.dataset.id,UI.pqty,undefined)){UI.pqty=1;render(true);toast(t('Added to cart'),'cart')}};
A.buyNow=el=>{if(addToCart(el.dataset.id,UI.pqty,undefined)){UI.pqty=1;go('cart')}};
/* ===== SERVICE PROVIDER ===== */
V.svc=id=>{const s=svc(id);if(!s)return V.nf();rec(id);const tabs=[['about','About'],['services','Services'],['gallery','Gallery'],['reviews','Reviews'],['contact','Contact']],tab=UI.stab2,rv=D().reviews.filter(r=>r.tid===id&&r.status==='published');let body='';
 if(tab==='about')body=`<div class="stack"><div class="card pad stack"><h3>${t('About')}</h3><p>${esc(s.desc)}</p><dl class="kv"><dt>${t('Service area')}</dt><dd>${esc(s.serviceArea)}</dd><dt>${t('Address')}</dt><dd>${esc(s.addr)}</dd></dl></div><div class="card pad stack"><h3>${t('Working hours')}</h3>${hoursTable(s.hours)}</div></div>`;
 if(tab==='services')body=`<div class="stack">${s.services.map(x=>`<div class="card pad row between"><b>${esc(x.n)}</b><span class="badge neu">${esc(x.p)}</span></div>`).join('')}${alertBox('info',t('Enquiry only for now. Booking and payment will come later.'))}</div>`;
 if(tab==='gallery')body=`<div class="grid g3">${s.gallery.map((g,i)=>`<button class="card" style="padding:0" data-act="lightbox" data-id="${id}" data-i="${i}" aria-label="${t('Open photo')} ${i+1}">${art(g,s.hue+i*20,'f')}</button>`).join('')}</div>`;
 if(tab==='reviews')body=`<div class="stack"><div class="card pad">${ratingBreak(rv)}</div><a class="btn p" href="#rev-${id}">${ic('star',18)} ${t('Write a review')}</a>${rv.map(r=>revCard(r,S.user&&r.uid==='u1')).join('')||empty('⭐','No reviews yet','Be the first to share your experience.')}</div>`;
 if(tab==='contact')body=`<div class="stack"><div class="card pad"><dl class="kv"><dt>${t('Phone')}</dt><dd><a href="${telH(s.phone)}">+91 ${esc(s.phone)}</a></dd><dt>WhatsApp</dt><dd>+91 ${esc(s.wa)}</dd><dt>${t('Address')}</dt><dd>${esc(s.addr)}</dd></dl></div>${mapSvg('smap',[s],{sel:s.id})}<a class="btn p" target="_blank" rel="noopener" href="${mapsDir(s)}">${ic('nav',18)} ${t('Get directions')}</a></div>`;
 return `<div class="stack" style="margin-bottom:6px"><div class="crumb"><a href="#home">${t('Home')}</a> / <a href="#cat-${s.cat}">${esc(catName(s.cat))}</a> / <span>${esc(nm(s.name))}</span></div>${s.status!=='approved'?unavailable(s):''}${profileHead(s,true)}</div>${actionBar(s,true)}
 <div class="card pad stack" style="margin-top:12px"><h3>${t('Send enquiry')}</h3><form data-form="enquiry" class="stack"><input type="hidden" name="sid" value="${id}">${field('Your name','name',S.user?S.user.name:'',{req:1,ac:'name'})}${field('Mobile number','phone',S.user?S.user.phone:'',{req:1,type:'tel',im:'numeric',pattern:'[0-9]{10}',ac:'tel',hint:'10 digits'})}${field('Message','msg','',{type:'textarea',req:1,ph:'Tell the provider what you need'})}${field('Preferred date','date','',{type:'date'})}<button class="btn p block">${ic('send',18)} ${t('Send enquiry')}</button></form></div>
 <div class="tabs" role="tablist" style="margin-top:14px">${tabs.map(([k,l])=>`<button role="tab" class="${tab===k?'on':''}" data-act="stab2" data-v="${k}">${t(l)}</button>`).join('')}</div>${body}`};
A.stab2=el=>{UI.stab2=el.dataset.v;render(true)};
F.enquiry=d=>{const e={id:rid('e'),sid:d.sid,name:d.name,phone:d.phone,msg:d.msg,date:d.date||'Any',ts:Date.now(),status:'new'};D().enq.unshift(e);notify(d.sid[0]==='s'?'provider':'vendor','New enquiry from '+d.name,d.msg,(d.sid[0]==='s'?'senq-':'venq-')+e.id,'enq');save();sheet(`<div class="state"><div class="ill">✅</div><h3>${t('Enquiry sent')}</h3><p>${t('The provider will call or WhatsApp you soon.')} ${t('Reference')}: ${e.id}</p><button class="btn p" data-act="closeSheet">${t('Done')}</button></div>`)};
/* ===== reviews write ===== */
function canReview(id){const k=id[0],oid=id.split('-')[0];if(!S.user)return{ok:false,login:true};const mine=D().orders.filter(o=>o.uid==='u1'&&['delivered','pickedup'].includes(o.status));
 if(k==='b'||k==='s'){const enq=D().enq.some(e=>e.sid===oid&&(e.phone===S.user.phone.replace(/\D/g,'').slice(-10)||e.name===S.user.name));return (mine.some(o=>o.bid===oid)||enq)?{ok:true}:{ok:false,msg:'Only customers who ordered from, or sent an enquiry to, this business can review it.'}}
 if(k==='p')return mine.some(o=>o.items.some(i=>i.pid===id))?{ok:true}:{ok:false,msg:'Only customers who bought this product can review it.'};
 if(k==='s')return D().enq.some(e=>e.sid===id&&e.phone===S.user.phone.replace(/\D/g,'').slice(-10))||D().enq.some(e=>e.sid===id&&e.name===S.user.name)?{ok:true}:{ok:false,msg:'Only people who sent an enquiry to this provider can review. Send an enquiry first.'};
 if(k==='r')return mine.some(o=>o.riderId===id)?{ok:true}:{ok:false,msg:'Only customers delivered by this rider can review.'};return{ok:false}}
const TAGS={b:['Fair price','Fresh','Helpful staff','On time','Clean'],p:['Good quality','Value for money','As described'],s:['Quick visit','Professional','Fair quote','Polite'],r:['Polite','On time','Careful']};
V.rev=id=>{const e=ent(id);if(!e)return V.nf();const c=canReview(id);const ex=D().reviews.find(r=>r.tid===id&&r.uid==='u1');
 if(c.login)return `<div class="state"><div class="ill">🔐</div><h3>${t('Log in to write a review')}</h3><p>${t('Only real customers can review.')}</p><a class="btn p" href="#login" data-act="loginNext">${t('Log in')}</a></div>`;
 if(!c.ok)return `<div class="stack"><button class="btn t sm" data-act="back" style="justify-self:start">${ic('cl',16)} ${t('Back')}</button><div class="state"><div class="ill">⭐</div><h3>${t('You can’t review this yet')}</h3><p>${t(c.msg)}</p><button class="btn p" data-act="back">${t('Go back')}</button></div></div>`;
 UI.star=ex?ex.rating:(UI.star||0);
 return `<div class="stack"><button class="btn t sm" data-act="back" style="justify-self:start">${ic('cl',16)} ${t('Back')}</button><h1>${ex?t('Edit your review'):t('Write a review')}</h1><div class="card pad row">${id[0]==='r'?'<div class="mini art">🛵</div>':art(e.emoji,e.hue,'mini')}<b>${esc(nm(e.name))}</b></div>
 <form data-form="review" class="stack"><input type="hidden" name="id" value="${id}"><input type="hidden" name="rating" id="rv_rating" value="${UI.star}"><div><div class="lbl">${t('Your rating')}</div><div class="row" role="radiogroup" aria-label="${t('Rating')}">${[1,2,3,4,5].map(i=>`<button type="button" class="iconbtn" style="width:52px;height:52px;color:${UI.star>=i?'var(--star)':'var(--border-strong)'}" data-act="star" data-v="${i}" role="radio" aria-checked="${UI.star===i}" aria-label="${i} ${t('stars')}"><svg class="ic fill" width="36" height="36" viewBox="0 0 24 24"><path d="${IC.star}"/></svg></button>`).join('')}</div></div>
 <div><div class="lbl small">${t('What went well?')}</div><div class="chips">${(TAGS[id[0]]||[]).map(x=>`<label class="chip"><input type="checkbox" name="tag_${esc(x)}" style="accent-color:var(--primary)" ${ex&&ex.tags.includes(x)?'checked':''}> ${esc(t(x))}</label>`).join('')}</div></div>
 ${field('Your review','text',ex?ex.text:'',{type:'textarea',req:1,ph:'Share a few words about your experience'})}${uploader('Add photos (optional)')}<button class="btn p block">${ex?t('Update review'):t('Submit review')}</button></form></div>`};
A.star=el=>{UI.star=+el.dataset.v;const f=$('#rv_rating');if(f)f.value=UI.star;$$('[data-act=star]').forEach(b=>{const on=+b.dataset.v<=UI.star;b.style.color=on?'var(--star)':'var(--border-strong)';b.setAttribute('aria-checked',+b.dataset.v===UI.star)})};
F.review=d=>{const r=+d.rating;if(!r){toast(t('Please choose a star rating'),'alert');return}const tags=Object.keys(d).filter(k=>k.startsWith('tag_')).map(k=>k.slice(4));const bad=/(http|www\.|\.com|idiot|spam)/i.test(d.text);let ex=D().reviews.find(x=>x.tid===d.id&&x.uid==='u1');const status=bad?'pending':'published';
 if(ex){Object.assign(ex,{rating:r,text:d.text,tags,status,ts:Date.now()})}else D().reviews.unshift({id:rid('rv'),type:d.id[0],tid:d.id,uid:'u1',name:S.user.name,rating:r,text:d.text,tags,ts:Date.now(),helpful:0,status,reply:''});
 const e=ent(d.id);const rs=D().reviews.filter(x=>x.tid===d.id&&x.status==='published');if(rs.length&&e&&d.id[0]!=='p'){e.rating=Math.round(rs.reduce((a,x)=>a+x.rating,0)/rs.length*10)/10;e.rc=Math.max(e.rc||0,rs.length)}
 notify(d.id[0]==='b'?'vendor':d.id[0]==='s'?'provider':d.id[0]==='r'?'rider':'vendor','New '+r+'★ review',d.text.slice(0,60),d.id[0]==='b'?'vreviews':d.id[0]==='s'?'sreviews':'rfeedback','review');save();UI.star=0;
 sheet(`<div class="state"><div class="ill">${status==='pending'?'⏳':'🎉'}</div><h3>${status==='pending'?t('Submitted for moderation'):t('Thanks for your review!')}</h3><p>${status==='pending'?t('Reviews with links or abusive words are checked by our team before they appear.'):t('Your review is now live.')}</p><button class="btn p" data-act="reviewDone">${t('Done')}</button></div>`)};
A.reviewDone=()=>{closeSheet();history.length>1?history.back():go('home')};
A.helpful=el=>{const r=D().reviews.find(x=>x.id===el.dataset.id);r.helpful=(r.helpful||0)+1;save();render(true)};
A.reportReview=el=>{const r=D().reviews.find(x=>x.id===el.dataset.id);r.reports=(r.reports||0)+1;if(r.status==='published'&&r.reports>=1)r.status='published';r.reported=true;notify('admin','Review reported','Review by '+r.name,'areviews','review');save();toast(t('Reported. Thank you.'),'flag')};
A.editReview=el=>go('rev-'+D().reviews.find(r=>r.id===el.dataset.id).tid);
A.delReview=el=>confirmBox(t('Delete this review?'),t('This cannot be undone.'),t('Delete'),()=>{D().reviews=D().reviews.filter(r=>r.id!==el.dataset.id);save();render(true);toast(t('Review deleted'),'trash')},true);
V.reviews=()=>{if(!S.user)return V.login();const l=D().reviews.filter(r=>r.uid==='u1');return `<div class="stack"><h1>${t('My reviews')}</h1>${l.length?l.map(r=>`<div class="stack" style="gap:4px"><a class="small bold" href="#${r.type==='b'?'biz':r.type==='p'?'prod':r.type==='s'?'svc':'biz'}-${r.tid}">${esc(nm(ent(r.tid)?ent(r.tid).name:{en:r.tid}))}</a>${revCard(r,true)}</div>`).join(''):empty('⭐','No reviews yet','After an order is delivered you can review the shop, product and rider.')}</div>`};
/* ===== bookmarks / offers / notifications ===== */
V.bookmarks=()=>{if(!S.user)return V.login();const tab=UI.saveTab,l=S.bookmarks.map(ent).filter(Boolean).filter(e=>tab==='b'?e.id[0]==='b':e.id[0]==='s');
 return `<div class="stack"><h1>${t('Saved')}</h1><div class="tabs"><button class="${tab==='b'?'on':''}" data-act="savetab" data-v="b">${t('Shops')}</button><button class="${tab==='s'?'on':''}" data-act="savetab" data-v="s">${t('Services')}</button></div>${l.length?`<div class="grid auto">${l.map(e=>`<div class="stack" style="gap:6px">${e.id[0]==='s'?svcCard(e):bizCard(e)}<button class="btn t sm" data-act="bm" data-id="${e.id}" style="justify-self:start">${ic('trash',16)} ${t('Remove')}</button></div>`).join('')}</div>`:empty('🔖','Nothing saved yet','Tap the bookmark on any shop or service to save it here.','<a class="btn p" href="#explore">'+t('Explore nearby')+'</a>')}</div>`};
A.savetab=el=>{UI.saveTab=el.dataset.v;render(true)};
V.offers=()=>{const f=UI.offCat||'',l=D().offers.filter(o=>o.status==='active'&&Date.now()<o.to&&(!f||biz(o.bid).cat===f));return `<div class="stack"><h1>${t('Offers & deals')}</h1><div class="chips"><button class="chip ${f?'':'on'}" data-act="offcat" data-v="">${t('All')}</button>${D().cats.map(c=>`<button class="chip ${f===c.id?'on':''}" data-act="offcat" data-v="${c.id}">${c.e} ${esc(nm(c))}</button>`).join('')}</div><div class="grid auto">${l.map(o=>{const b=biz(o.bid);return `<button class="card pad stack hover" style="text-align:left;background:linear-gradient(135deg,var(--offer-soft),var(--surface))" data-act="offerGo" data-id="${o.id}"><span class="badge offer" style="justify-self:start">${ic('tag',13)} ${o.type==='percent'?o.value+'% '+t('OFF'):o.type==='flat'?'₹'+o.value+' '+t('OFF'):t('Free delivery')}</span><h3>${esc(o.title)}</h3><div class="small t2">${esc(nm(b.name))} · ${t('till')} ${fdate(o.to)}</div></button>`}).join('')||empty('🏷️','No offers match','Try another category.')}</div></div>`};
A.offcat=el=>{UI.offCat=el.dataset.v;render(true)};
A.offerDetail=el=>{const o=D().offers.find(x=>x.id===el.dataset.id),b=biz(o.bid);o.views=(o.views||0)+1;save();sheet(`<h3>${esc(o.title)}</h3><p class="t2">${esc(nm(b.name))}</p><div class="stack" style="margin-top:10px"><dl class="kv"><dt>${t('Valid till')}</dt><dd>${fdate(o.to)}</dd><dt>${t('Applies to')}</dt><dd>${o.pids.length?o.pids.map(p=>nm(prod(p).name)).join(', '):t('Whole shop')}</dd></dl><div class="small muted"><b>${t('Terms')}:</b> ${t('Offer applies automatically at checkout. Cannot be combined with other shop offers. Shop may end the offer anytime.')}</div><a class="btn p block" href="#biz-${b.id}" data-act="closeSheet">${t('Visit shop')}</a></div>`)};
V.notifications=()=>{const l=D().notifs.cust;return `<div class="stack"><div class="row between"><h1>${t('Notifications')}</h1><button class="btn t sm" data-act="readAll" data-k="cust">${t('Mark all read')}</button></div><a class="btn g sm" href="#prefs" style="justify-self:start">${ic('sliders',16)} ${t('Notification preferences')}</a>${l.length?l.map(notifCard).join(''):empty('🔔','All caught up','New alerts will show here.')}</div>`};
